from __future__ import annotations

def rho_bisection(iterations: int = 80) -> float:
    if iterations <= 0:
        raise ValueError("iterations must be positive")
    lo, hi = 0.0, 1.0
    for _ in range(iterations):
        mid = (lo + hi) / 2.0
        if mid**3 + mid**2 < 1.0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0

if __name__ == "__main__":
    rho = rho_bisection()
    print(f"rho = {rho:.15f}")
    print(f"bracket-scale error bound < {2.0**-81:.3e}")

from __future__ import annotations

def plastic_newton(steps: int = 8, initial: float = 1.5) -> list[float]:
    if steps < 0:
        raise ValueError("steps must be nonnegative")
    values = [initial]
    p = initial
    for _ in range(steps):
        denominator = 3.0 * p * p - 1.0
        if denominator == 0.0:
            raise ZeroDivisionError("Newton derivative vanished")
        p -= (p**3 - p - 1.0) / denominator
        values.append(p)
    return values

if __name__ == "__main__":
    for index, value in enumerate(plastic_newton()):
        print(index, f"{value:.16f}", f"residual={value**3-value-1:+.3e}")

from __future__ import annotations

def padovan(count: int, initial: tuple[float, float, float] = (1.0, 1.0, 1.0)) -> list[float]:
    if count < 0:
        raise ValueError("count must be nonnegative")
    values = list(initial[:count])
    while len(values) < count:
        values.append(values[-3] + values[-2])
    return values

if __name__ == "__main__":
    p = 1.324717957244746
    values = padovan(30)
    for n in range(20, 29):
        ratio = values[n + 1] / values[n]
        print(n, f"ratio={ratio:.12f}", f"error={ratio-p:+.3e}")

